/**
 * Required ("key") fields per insight/chart type.
 *
 * The data comes from `required-fields.schema.json`, which is GENERATED by
 * `core/scripts/schema/generate_schema.py` from Plotly's plot-schema and copied
 * into `visivo/schema/` (then into this directory by `yarn copy-schemas`,
 * alongside the per-type `*.schema.json`). It is never edited by hand — add a
 * trace type or change a key field in the generator and regenerate.
 *
 * Each entry is `{ name, label, type, description, optional?, options?,
 * default?, fields? }`; `TracePropsEditor` opens these paths by default.
 */
import requiredFieldsArtifact from './required-fields.schema.json';

/** @type {Record<string, Array<object>>} */
export const REQUIRED_FIELDS = requiredFieldsArtifact.types || {};

/**
 * Get required fields for a chart type
 * @param {string} chartType - The chart type
 * @returns {Array} Array of required field configurations
 */
export function getRequiredFields(chartType) {
  return REQUIRED_FIELDS[chartType] || [];
}

/**
 * Check if a field is required for a chart type
 * @param {string} chartType - The chart type
 * @param {string} fieldName - The field name
 * @returns {boolean} True if the field is required
 */
export function isFieldRequired(chartType, fieldName) {
  return getRequiredFields(chartType).some(f => f.name === fieldName && !f.optional);
}

/**
 * Get all top-level field names (required and optional) for a chart type
 * @param {string} chartType - The chart type
 * @returns {Array<string>} Array of field names
 */
export function getAllFieldNames(chartType) {
  return getRequiredFields(chartType).map(field => field.name);
}
